TIMEOUT = 3.0  # 초
robots = {}

def on_state(rid, seq, t, pos):
    r = robots.get(rid)
    if r and seq <= r["seq"]:
        return f"{rid} seq={seq} 버림(옛 메시지)"
    robots[rid] = {"seq": seq, "t": t, "pos": pos}
    return f"{rid} seq={seq} 반영 pos={pos}"

def offline(now):
    return [rid for rid, r in robots.items() if now - r["t"] > TIMEOUT]

print(on_state("amr-01", 12, 1.0, (1, 3)))  # amr-01 seq=12 반영 pos=(1, 3)
print(on_state("amr-02", 5, 0.5, (7, 3)))   # amr-02 seq=5 반영 pos=(7, 3)
print(on_state("amr-01", 11, 1.1, (1, 2)))  # amr-01 seq=11 버림(옛 메시지)
print(on_state("amr-01", 13, 4.0, (1, 4)))  # amr-01 seq=13 반영 pos=(1, 4)
print(offline(4.2))                          # ['amr-02']
